def locate_even(numbers):
    positions = []
    for index, value in enumerate(numbers):
        if value % 2 == 0:
            positions.append(index)
    return positions

print(locate_even([7, 4, 9, 2]))  # [1, 3]

def count_increases(numbers):
    count = 0
    for index in range(len(numbers) - 1):
        if numbers[index + 1] > numbers[index]:
            count += 1
    return count

print(count_increases([3, 5, 4, 8]))  # 2

def character_counts(text):
    counts = {}
    for character in text:
        counts[character] = counts.get(character, 0) + 1
    return counts

print(character_counts("banana"))
# {'b': 1, 'a': 3, 'n': 2}

def are_anagrams(first, second):
    if len(first) != len(second):
        return False

    counts = {}
    for character in first:
        counts[character] = counts.get(character, 0) + 1
    for character in second:
        if character not in counts:
            return False
        counts[character] -= 1
        if counts[character] < 0:
            return False
    return True

print(are_anagrams("listen", "silent"))  # True

def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

print(is_palindrome("level"))  # True

def pair_sum_sorted(numbers, target):
    left, right = 0, len(numbers) - 1
    while left < right:
        current = numbers[left] + numbers[right]
        if current == target:
            return [left, right]
        if current < target:
            left += 1
        else:
            right -= 1
    return []

print(pair_sum_sorted([1, 3, 4, 7, 10], 11))  # [0, 4]

def two_sum_brute_force(numbers, target):
    for first in range(len(numbers)):
        for second in range(first + 1, len(numbers)):
            if numbers[first] + numbers[second] == target:
                return [first, second]
    return []

def two_sum(numbers, target):
    seen = {}
    for index, value in enumerate(numbers):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        seen[value] = index
    return []

print(two_sum([2, 7, 11, 15], 9))  # [0, 1]
print(two_sum([3, 3], 6))           # [0, 1]

def longest_unique_substring(text):
    left = 0
    last_seen = {}
    best_start = 0
    best_length = 0

    for right, character in enumerate(text):
        if character in last_seen:
            left = max(left, last_seen[character] + 1)
        last_seen[character] = right
        length = right - left + 1
        if length > best_length:
            best_start = left
            best_length = length

    return text[best_start:best_start + best_length]

print(longest_unique_substring("abcabcbb"))  # abc

def build_prefix_sum(numbers):
    prefix = [0]
    for value in numbers:
        prefix.append(prefix[-1] + value)
    return prefix

def range_sum(prefix, left, right):
    return prefix[right + 1] - prefix[left]

numbers = [3, 1, 4, 1, 5]
prefix = build_prefix_sum(numbers)
print(range_sum(prefix, 1, 3))  # 1 + 4 + 1 = 6
